/* @socom-skeleton body OpenKey__Q23zar4CZARFPCc */
namespace zar {
CKey* CZAR::OpenKey(const char* keyName)
	{
		CKey* key = NULL;

		if (!m_pFile)
			return NULL;

		if (!m_pFile->IsOpen())
			return NULL;

		if (m_keys.empty())
			key = m_root;
		else
			key = m_keys.front();

		key = key->FindKey(keyName);

		if (key)
			m_keys.insert(m_keys.begin(), key);

		return key;
	}
}

